 dict(pmid='43034549', doi='10.1016/j.ese.2026.100781', journal='Environ Sci Ecotechnol', title="Halving PM2.5 mortality by 2040: China's tightened air quality standard and residual disease burdens.", short='Peking University China GB 3095-2026 NAAQS 25 ug/m3 halving target PM2.5 attributable mortality comparative risk assessment 2013-2024', design='Burden / economic model', pm='Gridded high-resolution PM2.5 with disease-specific exposure-response functions; counterfactual compliance with 35 vs 25 ug/m3 annual limits', geo='China (mainland)', endpoint='PM2.5-attributable mortality by cause; progress toward WHO 2040 halving target', tier='B', basis='Model (CTM / LUR / ML)', affil='Peking University, China; Peking University, China', n="Comparative risk assessment for mainland China, 2013-2024, combining gridded PM2.5, gridded population and cause-specific exposure-response functions, scored against the WHO 2040 halving target and China's 2026 revision of the annual PM2.5 standard (GB 3095-2026) from 35 to 25 ug/m3. In 2024, full compliance with 25 ug/m3 would avert 4.3 times as many deaths as compliance with 35 ug/m3, and PM2.5-specific progress toward halving rises from 66.2% to 83.4%. Gains concentrate in COPD, stroke, lung cancer, LRI and IHD; dementia and type 2 diabetes respond little, and the dementia function is weakly supported. The abstract gives no absolute deaths or uncertainty intervals; the result is a counterfactual inherited from the chosen exposure-response shapes, not observed mortality change. Relevance: compliance below 25 ug/m3 is a range where low-cost sensor bias and humidity error become a large fraction of the margin being regulated.", sub=corpus.BURD),
 dict(pmid='', doi='10.1016/j.apr.2026.103273', journal='Atmospheric Pollution Research', title='Pollution characteristics and long-range transport of atmospheric microplastics during winter haze episodes in a megacity of northwest China', short='Xiao Du northwest China megacity winter haze atmospheric microplastics long-range transport', design='Metadata only (no abstract)', pm='Metadata only', geo='China (northwest)', endpoint='Metadata only', tier='C', basis='Not stated', affil='', n='Metadata only: no abstract in the Crossref deposit at issue time. Atmospheric Pollution Research paper on pollution characteristics and long-range transport of airborne microplastics during winter haze episodes in a northwest China megacity (first author Xiao, last author Du). No finding is asserted here. Relevance: indirect - microplastic fibres are a particle class optical PM sensors neither size nor count reliably; recheck for an abstract in the weekly sweep.', sub=corpus.EXPO),
 dict(pmid='', doi='10.1016/j.buildenv.2026.115576', journal='Building and Environment', title='Impacts of environmental control system operation modes on ultrafine particle pollution in subway station offices: A field experimental study', short='Guan Huang subway station offices environmental control system operation modes ultrafine particles field experiment', design='Metadata only (no abstract)', pm='Metadata only', geo='China (inferred from authors; not stated in record)', endpoint='Metadata only', tier='C', basis='Not stated', affil='', n='Metadata only: no abstract in the Crossref deposit at issue time. Building and Environment field experiment on how environmental control system operation modes affect ultrafine particle pollution in subway station offices (first author Guan, last author Huang). No finding is asserted here. Relevance: indirect - ultrafine number is invisible to Plantower-class mass sensors, so ventilation-mode effects of this kind are outside what distributed low-cost networks report; recheck in the weekly sweep.', sub=corpus.OCC),
 dict(pmid='43034507', doi='10.1177/27550834261493111', journal='J Med Access', title='Burden of stroke attributable to environmental, behavioral, and metabolic risk factors in Eastern Sub-Saharan Africa, from 1990 to 2023.', short='Arba Minch Bule Hora GBD 2023 Eastern Sub-Saharan Africa stroke attributable burden household air pollution 1990-2023', design='Burden estimation (GBD)', pm='GBD 2023 risk-factor exposure estimates incl. household air pollution from solid fuels and ambient PM', geo='Eastern Sub-Saharan Africa (GBD region incl. Ethiopia, Kenya)', endpoint='Stroke deaths and DALYs attributable to risk-factor groups', tier='C', basis='Model (CTM / LUR / ML)', affil='Arba Minch University, Ethiopia; Bule Hora University, Ethiopia', n='Secondary analysis of GBD 2023 for Eastern Sub-Saharan Africa. In 2023, stroke attributable to all risk factors accounted for 110,013 deaths (359 per 100,000; 95% UI 275-449) and 7,702 DALYs per 100,000 (6,043-9,495). Environmental risks contributed 4,146 DALYs per 100,000 (2,621-5,668), behind metabolic (6,286) and ahead of behavioural (2,505); household air pollution ranked third among single risks after systolic blood pressure and diet. No significant annualised decline in any risk category from 1990 to 2023. The abstract does not separate household from ambient PM within the environmental category, and every number is a GBD model output with sparse local monitoring or cohort input for this region. Relevance: the household-fuel PM term in East Africa rests on fuel-use proxies; kitchen-level sensor data are what would calibrate it.', sub=corpus.BURD),
